-- === FAQs (de) ===
INSERT INTO faqs (language, intent_name, question, answer, keywords) VALUES
-- Einträge basierend auf deiner faq_de.json (wo vorhanden) oder generiert
('de', 'faq_what_is_mindfluence', 'Was ist Mindfluence und was macht die App?', 'Mindfluence ist eine Streaming-App, die sich auf exklusive subliminale Audioinhalte spezialisiert hat. Diese Audios enthalten unterschwellige Affirmationen, oft kombiniert mit Technologien wie Binaural Beats oder isochronen Tönen, um Sie bei Ihrer persönlichen Entwicklung in Bereichen wie Schlaf, Fokus, Selbstvertrauen oder Entspannung zu unterstützen.', 'app, mindfluence, subliminal, persönliche entwicklung, was ist, funktion, konzept, streaming, audio, inhalte, unterschwellig, affirmationen, binaural beats, isochrone töne, schlaf, fokus, selbstvertrauen, entspannung, unterbewusstsein, erklärung'),
('de', 'faq_how_subliminals_work', 'Wie funktionieren subliminale Audios?', 'Subliminale Audios senden positive Affirmationen direkt an Ihr Unterbewusstsein, indem sie knapp unterhalb der bewussten Hörschwelle eingebettet werden. Das Ziel ist, positive Glaubenssätze zu verankern und Veränderungen auf einer tieferen Ebene zu fördern, ohne dass Sie die Affirmationen bewusst hören müssen.', 'subliminal, funktion, wirkungsweise, unterbewusstsein, affirmationen, audio, wie funktionieren, positiv, glaubenssätze, hören, hörschwelle, methode, technik, erklärung, effekt, veränderung, unterschwellig, botschaften'),
('de', 'faq_headphones_needed', 'Brauche ich Kopfhörer, um die Audios zu hören?', 'Für Audios, die Binaural Beats verwenden, sind Kopfhörer unbedingt erforderlich, da die Wirkung auf den unterschiedlichen Frequenzen für jedes Ohr basiert. Für andere Subliminals und isochrone Töne sind Kopfhörer zwar empfohlen, um Ablenkungen zu minimieren, aber nicht zwingend notwendig.', 'kopfhörer, binaural beats, hören, anwendung, technik, brauchen, nötig, erforderlich, benutzen, verwenden, subliminals, isochrone töne, ohne, frequenzen, ohr, stereo, lautsprecher, empfehlung'),
('de', 'faq_how_often_listen', 'Wie oft und wie lange sollte ich die Audios hören?', 'Regelmäßigkeit ist entscheidend. Wir empfehlen, die gewählten Audios täglich für mindestens 20-30 Minuten über einen Zeitraum von mehreren Wochen zu hören, um die besten Ergebnisse zu erzielen. Achten Sie auf die spezifischen Empfehlungen bei einzelnen Audios.', 'häufigkeit, dauer, anwendung, tipps, regelmässigkeit, oft, wie lange, hören, nutzung, zeit, audio, täglich, minuten, wochen, empfehlung, regelmäßig, ergebnisse, routine'),
('de', 'faq_find_audios', 'Wie finde ich passende Audios für meine Ziele?', 'Nutzen Sie die ''Entdecken''-Seite! Sie können nach Themen wie ''Schlaf'', ''Fokus'' oder ''Selbstvertrauen'' stöbern, die Suchfunktion verwenden oder sich unsere personalisierten Empfehlungen auf der Startseite ansehen.', 'finden, suchen, entdecken, kategorien, themen, empfehlungen, passende, audios, ziele, schlaf, fokus, selbstvertrauen, vorschläge, startseite, suchfunktion, auswahl, filtern'),
('de', 'faq_premium_benefits', 'Was sind die Vorteile eines Premium-Abonnements?', 'Mit Premium erhalten Sie werbefreies Hören, die Möglichkeit, Audios für die Offline-Nutzung herunterzuladen, oft höhere Audioqualität und Zugang zu exklusiven Inhalten oder längeren Sessions.', 'premium, abo, vorteile, werbefrei, offline, exklusiv, qualität, abonnement, mitgliedschaft, nutzen, plus, ohne werbung, herunterladen, download, audioqualität, inhalte, sessions'),
('de', 'faq_subscription_costs', 'Was kostet ein Abonnement?', 'Die genauen Preise für unsere verschiedenen Pläne (z.B. Basic, Premium, Family) finden Sie auf der ''Upgrade''-Seite in der App. Dort können Sie die Pläne auch vergleichen.', 'kosten, preis, abo, mitgliedschaft, upgrade, preise, abonnement, gebühren, bezahlung, geld, tarif, tarife, pläne, basic, premium, family, vergleichen'),
('de', 'faq_cancel_subscription', 'Wie kann ich mein Abonnement kündigen?', 'Sie können Ihr Abonnement jederzeit kündigen. Gehen Sie dazu in Ihrem Profil zum Tab ''Abonnement'' und wählen Sie die Option ''Abonnement kündigen'' oder ''Abonnement verwalten''. Ihr Zugang bleibt bis zum Ende des aktuellen Abrechnungszeitraums bestehen.', 'kündigen, abo beenden, cancel, mitgliedschaft kündigen, kündigung, abonnement, beenden, stornieren, storno, vertrag, löschen, entfernen, abmelden, jederzeit, profil, verwalten, abrechnungszeitraum'),
('de', 'faq_change_password', 'Wie kann ich mein Passwort ändern?', 'Gehen Sie in Ihrem Profil zum Tab ''Passwort''. Dort können Sie Ihr aktuelles Passwort eingeben und ein neues, sicheres Passwort festlegen. Achten Sie auf die angezeigten Passwortanforderungen.', 'passwort ändern, kennwort, sicherheit, konto, zugang, logindaten, aktualisieren, zurücksetzen, neu festlegen, profil, anforderungen'),
('de', 'faq_playback_error', 'Was tue ich, wenn ein Audio nicht abgespielt wird?', 'Überprüfen Sie zuerst Ihre Internetverbindung. Versuchen Sie, die App neu zu starten oder den Cache zu leeren. Wenn das Problem weiterhin besteht, insbesondere bei heruntergeladenen Inhalten, kontaktieren Sie bitte unseren Support.', 'fehler, wiedergabe, spielt nicht, problem, audio, support, cache, störung, funktioniert nicht, internetverbindung, app, heruntergeladen, download, kontakt'),
('de', 'faq_feature_list', 'Welche Funktionen gibt es?', 'Mindfluence bietet dir Streaming von Subliminals und Binaural Beats, persönliche Playlists, Offline-Downloads (Premium), Fortschrittsverfolgung und personalisierte Empfehlungen. Entdecke alle Möglichkeiten auf der "Entdecken"-Seite!', 'funktionen, features, was kann die app, umfang, möglichkeiten, liste, premium, offline, download, playlist, empfehlung, entdecken'),
('de', 'faq_app_updates', 'Gibt es Updates für die App?', 'Ja, wir entwickeln Mindfluence ständig weiter! Updates mit neuen Funktionen, Inhalten und Verbesserungen werden regelmäßig über deinen App Store (Apple App Store / Google Play Store) bereitgestellt. Aktiviere automatische Updates, um nichts zu verpassen.', 'app, update, updates, version, aktualisieren, neu, neuheiten, changelog, roadmap, app store, google play, automatisch'),
('de', 'faq_device_compatibility', 'Auf welchen Geräten läuft die App?', 'Mindfluence ist für moderne iOS- und Android-Smartphones und Tablets verfügbar. Lade sie einfach aus dem Apple App Store oder Google Play Store herunter. Eine Desktop- oder Web-Version gibt es aktuell nicht.', 'geräte, kompatibel, plattform, ios, android, iphone, ipad, smartphone, handy, tablet, pc, mac, web, browser, systemanforderungen, betriebssystem, app store, google play'),
('de', 'faq_offline_mode', 'Kann ich die App offline nutzen?', 'Ja! Mit einem Mindfluence Premium-Abonnement kannst du deine Lieblingsaudios herunterladen und sie überall anhören, auch ohne aktive Internetverbindung – perfekt für unterwegs oder im Flugzeug.', 'offline, modus, download, herunterladen, ohne internet, ohne wlan, flugmodus, hören, wiedergabe, speichern, premium, abo, funktion, vorteil'),
('de', 'faq_show_alternatives', 'Gibt es Alternativen zu Mindfluence?', 'Es gibt verschiedene Apps für Meditation und mentales Wohlbefinden. Mindfluence hebt sich durch den starken Fokus auf Subliminals und audiotechnologische Unterstützung (wie Binaural Beats) ab. Welche App am besten zu dir passt, hängt von deinen persönlichen Zielen ab.', 'alternative, anders, optionen, vergleich, ähnlich, konkurrenz, markt, meditation, achtsamkeit, app, subliminal, binaural beats'),
('de', 'faq_download_offline', 'Wie lade ich Audios herunter?', 'Als Premium-Mitglied siehst du neben vielen Tracks ein Download-Symbol (meist eine Wolke mit Pfeil). Tippe darauf, und das Audio wird für die Offline-Nutzung gespeichert. Du findest deine Downloads im entsprechenden Bereich der App.', 'download, anleitung, herunterladen, speichern, offline, button, finden, wie, premium, symbol, wolke, pfeil'),
('de', 'faq_change_email', 'E-Mail Adresse ändern', 'Du kannst deine E-Mail-Adresse in deinem Profil unter dem Abschnitt "Persönliche Daten" oder "Kontoeinstellungen" ändern. Möglicherweise musst du die neue Adresse per E-Mail bestätigen.', 'email, mail, adresse ändern, aktualisieren, kontaktdaten, profil, konto, einstellungen, benutzerdaten, wechseln, bestätigen'),
('de', 'faq_delete_account', 'Konto löschen', 'Wenn du dein Konto endgültig löschen möchtest, findest du die Option dafür in deinen Profileinstellungen (oft unter "Konto verwalten" oder "Datenschutz"). Achtung: Alle deine Daten und Abos gehen dabei verloren und der Vorgang ist nicht umkehrbar.', 'konto löschen, account entfernen, profil löschen, daten löschen, dauerhaft, unwiderruflich, schließen, kündigen, abmelden, datenschutz, dsgvo, einstellungen'),
('de', 'faq_login_error', 'Kann mich nicht einloggen', 'Prüfe bitte deine E-Mail und dein Passwort genau. Nutze die "Passwort vergessen"-Funktion, falls nötig. Stelle sicher, dass deine Internetverbindung stabil ist. Wenn es weiterhin nicht klappt, melde dich beim Support.', 'login, anmelden, anmeldung, fehler, probleme, passwort falsch, kennwort, zugang, email, internet, verbindung, support, hilfe, passwort vergessen'),
('de', 'faq_data_security', 'Sind meine Daten sicher?', 'Ja, deine Datensicherheit ist uns sehr wichtig. Wir nutzen Verschlüsselung und halten uns streng an die DSGVO. Deine Daten werden nicht verkauft. Details findest du in der Datenschutzerklärung.', 'daten, sicherheit, datenschutz, dsgvo, gdpr, sicher, schutz, verschlüsselung, https, passwort, hashing, speichern, übertragung, verkauf, privacy, policy'),
('de', 'faq_scientific_basis', 'Ist das wissenschaftlich bewiesen?', 'Die Wirkung von Techniken wie Subliminals und Binaural Beats wird wissenschaftlich erforscht, es gibt Studien, die Effekte nahelegen. Die individuelle Erfahrung kann aber variieren. Mindfluence ist ein unterstützendes Werkzeug, kein medizinisches Heilmittel.', 'wissenschaftlich, bewiesen, studie, studien, wirksamkeit, beleg, beweise, forschung, subliminal, binaural beats, isochrone töne, evidenz, validität, placebo, effekt, ergebnisse, disclaimer'),
('de', 'faq_medical_disclaimer', 'Ersetzt das eine Therapie?', 'Nein, Mindfluence ersetzt keine ärztliche oder psychotherapeutische Behandlung. Es dient der Unterstützung des Wohlbefindens. Bei gesundheitlichen Beschwerden konsultiere bitte immer einen Arzt oder Therapeuten.', 'medizin, therapie, psychotherapie, arzt, therapeut, behandlung, diagnose, ersatz, disclaimer, gesundheit, psychisch, probleme, professionell, hilfe, krankheit'),
('de', 'faq_find_invoice', 'wo finde ich meine rechnungen', 'Deine Rechnungen und die Übersicht deiner Zahlungen findest du in deinem Profilbereich, normalerweise unter "Abonnement & Abrechnung" oder "Zahlungshistorie".', 'rechnung, rechnungen, finden, sehen, download, herunterladen, zahlung, zahlungshistorie, abbuchung, beleg, quittung, historie, verlauf, kostenaufstellung, profil, konto, abrechnung, abo'),
('de', 'faq_general', 'Ich habe eine allgemeine Frage.', 'Okay, frag einfach! Ich versuche mein Bestes, dir zu helfen oder dich an die richtige Stelle zu leiten. Je genauer deine Frage, desto besser kann ich antworten.', 'allgemein, frage, info, hilfe, sonstiges'),
('de', 'faq_session_duration_impact', 'Macht es einen Unterschied, ob ich 10 oder 30 Minuten höre?', 'Ja, tendenziell schon. Längere Hörzeiten (z.B. 20-30 Min.) geben deinem Unterbewusstsein mehr Zeit, die Affirmationen und Frequenzen aufzunehmen. Kurze Sessions können aber auch schon positive Impulse setzen. Regelmäßigkeit ist oft wichtiger als die einzelne Dauer.', 'hördauer, dauer, zeit, lang, kurz, unterschied, wirkung, effekt, 10 minuten, 30 minuten, empfehlung, regelmäßig, tiefe'),
('de', 'faq_refund_annual_subscription', 'Kann ich mein Jahresabo vorzeitig kündigen und Geld zurückbekommen?', 'Ein Jahresabo wird als vergünstigtes Paket für 12 Monate im Voraus bezahlt. Eine anteilige Rückerstattung bei Kündigung vor Ablauf der 12 Monate ist daher in der Regel nicht möglich. Dein Zugang bleibt bis zum Ende des bezahlten Jahres bestehen.', 'jahresabo, kündigen, vorzeitig, rückerstattung, geld zurück, anteilig, bedingungen, agb, laufzeit, rabatt'),
('de', 'faq_payment_security', 'Wie sicher ist meine Zahlungsinformation?', 'Sehr sicher! Wir arbeiten mit zertifizierten Zahlungsdienstleistern (wie Stripe) zusammen, die höchste Sicherheitsstandards (PCI-DSS) erfüllen. Deine vollständigen Kartendaten werden nie auf unseren Servern gespeichert.', 'zahlung, sicherheit, zahlungsinformation, kreditkarte, daten, sicher, verschlüsselt, pci dss, stripe, zahlungsdienstleister, speichern, datenschutz'),
('de', 'faq_combine_subliminals_meditation', 'Kann ich Subliminals gleichzeitig mit Meditation hören?', 'Absolut! Das kann eine sehr wirkungsvolle Kombination sein. Du kannst ein passendes Subliminal im Hintergrund laufen lassen, während du deine Meditationsübung durchführst.', 'kombinieren, subliminal, meditation, gleichzeitig, hören, anwendung, praxis, achtsamkeit, entspannung, synergie'),
('de', 'faq_multitasking_effectiveness', 'Wirken die Audios auch, wenn ich nebenbei etwas anderes mache?', 'Die unterschwelligen Affirmationen sollen auch dann wirken, wenn deine bewusste Aufmerksamkeit woanders ist. Für optimale Ergebnisse, besonders bei Entspannungs- oder Fokusübungen, empfehlen wir aber, dir eine ruhige Zeit ohne Ablenkungen zu nehmen.', 'multitasking, nebenbei, ablenkung, wirkung, effektivität, hören, subliminal, unterbewusstsein, fokus, entspannung, empfehlung, aufmerksamkeit'),
('de', 'faq_account_recovery', 'Ich habe keinen Zugriff mehr auf meine E-Mail, wie komme ich an mein Konto?', 'Das ist knifflig. Bitte kontaktiere umgehend unseren Support unter support@mindfluence.app. Wir werden versuchen, deine Identität zu verifizieren und dir zu helfen, wieder Zugang zu erhalten.', 'konto wiederherstellen, zugang verloren, email verloren, kein zugriff, login problem, hilfe, support, verifizierung, identität, kontakt'),
('de', 'faq_sound_quality_issues', 'Der Ton klingt schlecht oder verzerrt.', 'Prüfe bitte deine Kopfhörer oder Lautsprecher und die Verbindung. Tritt das Problem nur bei Mindfluence auf? Starte die App neu und prüfe deine Internetverbindung (beim Streamen). Wenn du offline hörst, lade das Audio erneut herunter. Hilft das alles nicht, melde dich beim Support.', 'tonqualität, sound, schlecht, verzerrt, knackt, rauscht, probleme, fehler, kopfhörer, verbindung, internet, download, streaming, support, troubleshooting'),
('de', 'faq_shared_wifi', 'Kann ich die App im öffentlichen WLAN nutzen?', 'Ja, das geht. Sei aber in öffentlichen WLANs generell vorsichtig, besonders beim Login. Die Verbindung zu unseren Servern ist zwar verschlüsselt (HTTPS), aber das WLAN selbst könnte unsicher sein. Für störungsfreies Hören unterwegs sind Downloads (Premium) ideal.', 'wlan, wifi, öffentlich, hotspot, netzwerk, sicherheit, nutzen, streaming, download, verschlüsselung, https, café, flughafen'),
('de', 'faq_beta_testing', 'Kann ich Beta-Tester werden?', 'Wir freuen uns über dein Interesse! Wenn wir Beta-Tester für neue Versionen suchen, geben wir das meist über unseren Newsletter oder Social Media bekannt. Folge uns dort, um auf dem Laufenden zu bleiben!', 'beta test, tester, programm, teilnehmen, mitmachen, neue funktionen, vorschau, feedback, ankündigung, newsletter'),
('de', 'faq_content_duration_sleep', 'Warum sind Schlaf-Audios oft so lang?', 'Schlaf-Audios sind oft länger gestaltet (z.B. 1-2 Stunden oder sogar Endlosschleifen), um dich sanft in den Schlaf zu begleiten und auch während der Nacht unterstützend zu wirken, falls du aufwachst. Sie sollen eine beruhigende Klangumgebung schaffen.', 'schlaf, audio, dauer, länge, lang, nacht, einschlafen, durchschlafen, tiefschlaf, wirkung, grund, stunden'),
('de', 'faq_search_tips', 'Habt ihr Tipps für die Suche nach Audios?', 'Klar! Sei spezifisch, aber probiere auch Synonyme (z.B. "Ruhe", "Gelassenheit", "Entspannung"). Nutze die Filter nach Kategorien. Schau dir auch die Keywords bei ähnlichen Audios an, die dir gefallen.', 'suche, suchen, finden, tipps, trick, stichwörter, keywords, filter, kategorien, entdecken, audio, inhalte, synonyme'),
('de', 'faq_cancel_during_trial', 'Kann ich während der Testphase kündigen?', 'Ja, absolut. Du kannst ein kostenloses Probeabo jederzeit vor Ablauf der Testphase in deinen Abo-Einstellungen kündigen, damit dir keine Kosten entstehen. Der Premium-Zugang bleibt dir bis zum Ende der Testphase erhalten.', 'testphase, probeabo, kündigen, während, kostenlos, frist, rechtzeitig, verhindern, kosten, abo, einstellungen, jederzeit'),
('de', 'faq_data_usage_streaming', 'Verbraucht das Streamen viel Datenvolumen?', 'Audio-Streaming verbraucht weniger Daten als Video, aber es summiert sich. Eine Stunde Audio in guter Qualität kann ca. 60-100 MB verbrauchen. Wenn du mobil viel hörst, achte auf dein Datenlimit oder nutze die Download-Funktion (Premium) im WLAN.', 'datenvolumen, verbrauch, streaming, mobilfunk, mobile daten, internet, kosten, viel, mb, gb, offline, download, wlan, sparen'),
('de', 'faq_subliminals_while_driving', 'Darf ich Subliminals beim Autofahren hören?', 'NEIN, auf keinen Fall! Audios zur Entspannung, zum Schlaf oder mit Gehirnwellen-Stimulation (Binaural Beats etc.) dürfen NIEMALS beim Autofahren oder bei anderen Tätigkeiten gehört werden, die deine volle Aufmerksamkeit erfordern. Das ist gefährlich!', 'autofahren, autofahrt, fahren, sicherheit, hören, subliminal, binaural beats, entspannung, schlaf, aufmerksamkeit, konzentration, warnung, verboten, gefährlich'),
('de', 'faq_age_restriction', 'Gibt es eine Altersbeschränkung für die App?', 'Ja, du musst mindestens 18 Jahre alt sein, um ein Konto zu erstellen und ein Abonnement abzuschließen. Die Inhalte sind für Erwachsene gedacht. Minderjährige dürfen die App nur mit Zustimmung und unter Aufsicht der Erziehungsberechtigten nutzen.', 'altersbeschränkung, jugendschutz, nutzungsbedingungen, agb, mindestalter, 18 jahre, kinder, eltern, zustimmung'),
('de', 'faq_evidence_vs_belief', 'Muss ich an die Wirkung glauben, damit es funktioniert?', 'Eine offene und positive Einstellung kann den Prozess unterstützen. Die zugrundeliegenden Techniken wie Affirmationen und Frequenzstimulation zielen jedoch darauf ab, auch auf unterbewusster Ebene zu wirken. Regelmäßige Anwendung ist meist der Schlüssel, unabhängig vom festen Glauben.', 'glaube, glauben, wirkung, funktionieren, placebo, einstellung, positiv, offenheit, wissenschaft, unterbewusstsein, gehirnwellen, skepsis'),
('de', 'faq_payment_receipt', 'Bekomme ich eine Quittung für meine Zahlung?', 'Ja, nach jeder erfolgreichen Abo-Zahlung erhältst du automatisch eine Bestätigungs-E-Mail, die auch als Beleg dient. Deine komplette Zahlungshistorie mit Rechnungsdetails findest du zudem in deinem Profilbereich.', 'rechnung, quittung, beleg, zahlungsbestätigung, email, bekommen, erhalten, zahlung, abo, historie, profil, nachweis'),
('de', 'faq_playlist_limit', 'Gibt es ein Limit für Playlists oder gespeicherte Tracks?', 'Aktuell gibt es keine harten Limits für die Anzahl der Playlists, die du erstellen kannst, oder die Tracks, die du als Favoriten speichern kannst. Bei Offline-Downloads (Premium) ist das Limit natürlich der verfügbare Speicherplatz auf deinem Gerät.', 'limit, begrenzung, anzahl, playlists, wiedergabelisten, favoriten, tracks, speichern, herunterladen, download, wie viele, unbegrenzt'),
('de', 'faq_offline_playback_quality', 'Ist die Qualität der heruntergeladenen Audios anders?', 'Du kannst in den Einstellungen oft wählen, in welcher Qualität du Audios herunterladen möchtest (Standard vs. Hoch). Die Offline-Qualität entspricht dann der gewählten Download-Qualität und ist unabhängig von deiner Internetverbindung beim Hören.', 'offline, download, audioqualität, qualität, unterschied, streaming, besser, schlechter, bitrate, premium, einstellungen, hoch, standard'),
('de', 'faq_pause_subscription', 'Kann ich mein Abo pausieren statt zu kündigen?', 'Eine direkte Pausieren-Funktion bieten wir momentan nicht an. Du kannst aber dein Abo zum Ende der Laufzeit kündigen und später einfach wieder ein neues Abo abschließen, wenn du die App erneut nutzen möchtest.', 'abo pausieren, pause, unterbrechen, mitgliedschaft, abonnement, statt kündigen, möglichkeit, funktion, alternative, kündigen, neu starten'),
('de', 'faq_subliminal_language_impact', 'Wirken deutsche Subliminals auch, wenn meine Muttersprache Englisch ist?', 'Die Wirkung ist am stärksten in deiner Muttersprache, da das Unterbewusstsein die Nuancen am besten versteht. Deutsche Affirmationen können aber dennoch einen positiven Effekt haben, wenn du die Sprache gut verstehst. Wir bieten Inhalte in beiden Sprachen an.', 'subliminal, sprache, wirkung, muttersprache, anderssprachig, deutsch, englisch, verstehen, unterbewusstsein, affirmation, effektivität'),
('de', 'faq_isochronic_tones_safety', 'Sind isochrone Töne sicher?', 'Isochrone Töne sind rhythmische Klangpulse und gelten für die meisten Menschen als sicher. Wie bei allen Klangstimulationen sollten Personen mit Epilepsie oder neurologischen Besonderheiten vorsichtshalber ärztlichen Rat einholen.', 'isochrone töne, sicherheit, sicher, gefahr, risiko, nebenwirkungen, epilepsie, neurologisch, gesundheit, arzt fragen, warnung'),
('de', 'faq_listening_with_others', 'Kann ich die Audios zusammen mit anderen hören (z.B. Partner)?', 'Audios ohne Binaural Beats (also reine Subliminals oder mit isochronen Tönen) können problemlos über Lautsprecher gehört werden, auch von mehreren Personen. Für Binaural Beats braucht jede Person eigene Stereo-Kopfhörer.', 'zusammen hören, gemeinsam, partner, andere personen, lautsprecher, kopfhörer, binaural beats, subliminal, isochrone töne, familie'),
('de', 'faq_changing_affirmations', 'Ändern sich die Affirmationen in den Audios manchmal?', 'Die Kernbotschaften bleiben stabil. Wir können aber Audios überarbeiten, um die Formulierungen oder die Klangqualität zu verbessern. Solche Updates ersetzen dann die alte Version in der Bibliothek.', 'affirmationen, ändern, updates, version, neu, optimiert, inhalt, audio, überarbeitet, qualität'),
('de', 'faq_delete_downloaded_content', 'Wie lösche ich heruntergeladene Inhalte?', 'Gehe in den "Downloads"-Bereich der App. Dort siehst du alle offline gespeicherten Audios. Wähle das Audio aus, das du entfernen möchtest, und suche nach einer Option wie "Löschen" oder einem Mülleimer-Symbol.', 'download, löschen, entfernen, offline, inhalte, audio, datei, speicherplatz, verwalten, anleitung, wie'),
('de', 'faq_account_security_tips', 'Habt ihr Tipps für die Kontosicherheit?', 'Unbedingt! Nutze ein starkes, einzigartiges Passwort (Passwortmanager hilft!). Aktiviere Zwei-Faktor-Authentifizierung (2FA). Gib deine Login-Daten nie weiter. Logge dich auf fremden Geräten aus. Sei vorsichtig bei Phishing-Mails.', 'kontosicherheit, sicherheit, tipps, passwort, stark, einzigartig, 2fa, zwei-faktor-authentifizierung, schutz, login, abmelden, daten teilen, phishing'),
('de', 'faq_push_notifications', 'Wofür sind die Push-Benachrichtigungen?', 'Wir nutzen sie sparsam, um dich über wirklich relevante Dinge zu informieren: Neue Audios in deinen Lieblingsthemen, wichtige App-Updates oder exklusive Angebote. Du kannst sie in den Einstellungen anpassen.', 'push benachrichtigungen, notifications, mitteilungen, wofür, zweck, inhalt, neu, angebot, update, einstellungen, deaktivieren, anpassen'),
('de', 'faq_troubleshooting_general', 'Die App funktioniert nicht richtig, was sind erste Schritte?', 'Standard-Tipps: 1. Internet checken. 2. App komplett schließen & neu starten. 3. Handy/Tablet neu starten. 4. App-Cache leeren (Anleitung googeln für dein Gerät). 5. App & OS auf Updates prüfen. 6. Wenn nichts hilft: Support kontaktieren!', 'problembehandlung, troubleshooting, hilfe, fehler, funktioniert nicht, app, erste schritte, internet, neustart, cache leeren, update, support, anleitung'),
('de', 'faq_social_media', 'Seid ihr auf Social Media?', 'Ja, klar! Folge uns auf Facebook und Instagram für Inspirationen, News und Community-Austausch. Die Links findest du auf unserer Website.', 'social media, soziale netzwerke, facebook, instagram, twitter, youtube, linkedin, finden, folgen, community, kontakt, links, profile'),
('de', 'faq_binaural_vs_isochronic', 'Was ist besser: Binaural Beats oder isochrone Töne?', 'Beide zielen auf Gehirnwellen-Synchronisation ab. Binaural Beats brauchen Kopfhörer und wirken subtiler "im Kopf". Isochrone Töne sind direkte Pulse, brauchen keine Kopfhörer und werden von manchen als intensiver empfunden. Es ist sehr individuell, was besser wirkt.', 'binaural beats, isochrone töne, unterschied, vergleich, was ist besser, wirkung, effektivität, kopfhörer, lautsprecher, technik, präferenz'),
('de', 'faq_affirmation_volume', 'Kann ich die Lautstärke der Affirmationen separat regeln?', 'Nein, die Lautstärke der unterschwelligen Affirmationen ist fest eingestellt und nicht separat regelbar. Sie müssen unter der bewussten Hörschwelle bleiben, um ihre Wirkung zu entfalten.', 'affirmationen, lautstärke, regeln, einstellen, separat, subliminal, unterschwellig, leise, audio, mix, pegel'),
('de', 'faq_listening_while_working', 'Kann ich die Audios während der Arbeit hören?', 'Für Fokus und Konzentration gedachte Audios sind dafür oft gut geeignet. Tiefenentspannungs-Audios eher nicht. Achte darauf, dass es dich nicht ablenkt und die Lautstärke passt. Reine Subliminals ohne starke Beats stören meist am wenigsten.', 'arbeit, lernen, während arbeit, hören, büro, fokus, konzentration, audio, subliminal, ablenkung, produktivität, kopfhörer'),
('de', 'faq_effects_duration', 'Wie lange hält die Wirkung eines Audios an?', 'Die direkte Wirkung (z.B. Entspannung) hält oft einige Zeit nach dem Hören an. Die langfristigen Effekte durch Umprogrammierung des Unterbewusstseins (z.B. bei Selbstvertrauen) sollen dauerhaft sein, erfordern aber regelmäßige Anwendung über Wochen oder Monate.', 'wirkung, dauer, wie lange, anhält, effekt, spürbar, kurzfristig, langfristig, nachhaltig, veränderung, subliminal, anwendung, gewohnheit'),
('de', 'faq_can_i_share_account', 'Kann ich mein Konto mit anderen teilen?', 'Nein, laut unseren Nutzungsbedingungen ist dein Konto personengebunden und darf nicht geteilt werden. Für die gemeinsame Nutzung im Haushalt bieten wir den Familienplan an.', 'konto teilen, account sharing, mehrere nutzer, familie, freunde, abo, abonnement, erlaubnis, bedingungen, agb, nicht erlaubt, nutzungsbedingungen'),
('de', 'faq_payment_failed', 'Meine Zahlung ist fehlgeschlagen, was nun?', 'Überprüfe bitte die Daten deiner Zahlungsmethode (Gültigkeit, Limit, Deckung). Aktualisiere sie ggf. in deinem Profil. Manchmal blockiert auch die Bank eine Transaktion. Kontaktiere deine Bank oder unseren Support, wenn das Problem bestehen bleibt.', 'zahlung fehlgeschlagen, zahlungsproblem, abbuchung, fehler, kreditkarte, paypal, abo, abonnement, problem, hilfe, support, aktualisieren, bank, limit, deckung'),
('de', 'faq_supported_countries', 'In welchen Ländern ist die App verfügbar?', 'Mindfluence ist in den meisten Ländern über den Apple App Store und Google Play verfügbar. Die genaue Verfügbarkeit von Zahlungsmethoden oder spezifischen Inhalten kann regional leicht abweichen.', 'verfügbar, länder, regionen, international, weltweit, app store, google play, download, einschränkungen, wo'),
('de', 'faq_storage_space', 'Wie viel Speicherplatz benötigen die Downloads?', 'Das variiert stark je nach Länge und Qualität des Audios. Eine 30-minütige Session in hoher Qualität kann durchaus 50-100 MB benötigen. In den App-Einstellungen kannst du oft die Download-Qualität wählen, um Speicher zu sparen.', 'speicherplatz, größe, download, offline, audio, datei, wie viel, benötigen, voll, verwalten, löschen, mb, gb, qualität'),
('de', 'faq_background_playback', 'Kann ich hören, wenn die App im Hintergrund ist oder der Bildschirm aus ist?', 'Ja, das ist eine Kernfunktion. Starte ein Audio und nutze dein Handy weiter oder sperre den Bildschirm – die Wiedergabe läuft im Hintergrund weiter.', 'hintergrund, wiedergabe, abspielen, app geschlossen, bildschirm aus, sperrbildschirm, multitasking, funktion, läuft weiter, musik'),
('de', 'faq_custom_affirmations', 'Kann ich eigene Affirmationen hinzufügen oder verwenden?', 'Diese Funktion bieten wir aktuell nicht an. Unsere Affirmationen sind sorgfältig formuliert und in die Audios integriert. Du kannst uns aber gerne Feedback geben, welche Themen oder Affirmationen du dir wünschen würdest.', 'eigene affirmationen, hinzufügen, erstellen, benutzerdefiniert, anpassen, audio, funktion, feature, nicht möglich, wunsch, feedback'),
('de', 'faq_specific_frequencies_meaning', 'Was bedeuten die spezifischen Frequenzen wie 5Hz oder 10Hz?', 'Das sind Frequenzen im Bereich der Gehirnwellen. 5Hz liegt im Theta-Bereich (tiefe Entspannung/Meditation), 10Hz im Alpha-Bereich (entspannte Wachheit). Binaural Beats mit diesen Frequenzen sollen dein Gehirn anregen, auf dieser Frequenz zu schwingen (Resonanz).', 'frequenzen, hertz, hz, 5hz, 10hz, bedeutung, gehirnwellen, delta, theta, alpha, beta, gamma, binaural beats, technik, wirkung, resonanz'),
('de', 'faq_stereo_mono_headphones', 'Müssen es Stereo-Kopfhörer sein oder gehen auch Mono?', 'Für Binaural Beats: Ja, unbedingt Stereo! Der Effekt entsteht durch unterschiedliche Töne links und rechts. Für reine Subliminals oder isochrone Töne ist Mono technisch ausreichend, aber Stereo gibt generell ein besseres Klangerlebnis.', 'kopfhörer, stereo, mono, unterschied, voraussetzung, notwendig, binaural beats, technik, effekt, subliminal, isochrone töne'),
('de', 'faq_listening_volume_binaural', 'Wie laut sollte ich Binaural Beats hören?', 'Moderat und angenehm. Du solltest die Töne und den Beat wahrnehmen, aber sie sollten nicht unangenehm oder aufdringlich sein. Finde eine Lautstärke, bei der du dich entspannen kannst. Zu laut ist nicht besser!', 'lautstärke, binaural beats, hören, empfehlung, wie laut, moderat, angenehm, leise, pegel, kopfhörer, schutz'),
('de', 'faq_feeling_nothing', 'Ich höre die Audios, aber spüre (noch) nichts. Ist das normal?', 'Total normal! Die Wirkung ist oft subtil und nicht sofort ein "Wow"-Effekt. Besonders bei Subliminals arbeitet das Unterbewusstsein im Hintergrund. Gib dir Zeit, höre regelmäßig und achte auf kleine Veränderungen über Wochen.', 'wirkung, effekt, spüre nichts, fühle nichts, kein unterschied, normal, geduld, zeit, prozess, regelmäßig, anwendung, subliminal, binaural beats, subtil'),
('de', 'faq_headache_discomfort', 'Ich bekomme Kopfschmerzen oder fühle mich unwohl beim Hören.', 'Sofort leiser stellen oder Pause machen! Das kann bei zu hoher Lautstärke passieren oder wenn du empfindlich auf die Frequenzen reagierst. Wenn es anhält, nutze das Audio nicht weiter und konsultiere bei Bedenken einen Arzt.', 'kopfschmerzen, unwohl, schwindel, übelkeit, nebenwirkungen, problem, hören, lautstärke, pause, arzt, warnung, empfindlich, frequenz'),
('de', 'faq_managing_family_members', 'Wie verwalte ich die Mitglieder meines Familienplans?', 'Als Admin des Familienplans kannst du in deinen Abo-Einstellungen sehen, wer eingeladen ist, Einladungen versenden (meist per E-Mail-Link) und Mitglieder wieder entfernen.', 'familienplan, family plan, verwalten, administration, mitglieder, hinzufügen, einladen, entfernen, löschen, abo, einstellungen, admin'),
('de', 'faq_switching_devices_playback', 'Kann ich auf einem Gerät anhalten und auf einem anderen weiterhören?', 'Ja, dein Hörfortschritt wird mit deinem Konto synchronisiert. Du kannst auf dem Handy anhalten und auf dem Tablet genau dort weitermachen, wo du aufgehört hast.', 'gerätewechsel, geräte, synchronisation, fortschritt, wiedergabe, anhalten, fortsetzen, weiterhören, konto, nahtlos, sync'),
('de', 'faq_subscription_payment_date', 'Wann wird mein Abo immer abgebucht?', 'Die Abbuchung erfolgt zyklisch, meist an dem Tag des Monats (oder Jahres), an dem du das Abo ursprünglich gestartet hast. Das genaue nächste Datum siehst du in deinen Abo-Details.', 'abbuchung, zahlung, datum, wann, tag, monat, jahr, abrechnung, zyklus, periode, fälligkeit, abo, profil, verlängerung'),
('de', 'faq_contact_support_response_time', 'Wie schnell antwortet der Support?', 'Unser Ziel ist es, Anfragen innerhalb von 24-48 Stunden an Werktagen zu beantworten. Je nach Anfrageaufkommen kann es manchmal etwas länger dauern. Wir bitten um Geduld.', 'support, antwortzeit, wie schnell, dauer, bearbeitung, kundendienst, kundenservice, kontakt, email, ticket, werktage, wartezeit'),
('de', 'faq_background_data_usage', 'Verbraucht die App auch Daten, wenn ich sie nicht aktiv nutze?', 'Minimal. Für Hintergrundprozesse wie das Synchronisieren deines Fortschritts oder das Empfangen von Push-Nachrichten werden nur sehr kleine Datenmengen benötigt. Der Hauptverbrauch entsteht beim Streamen.', 'datenverbrauch, datenvolumen, hintergrund, inaktiv, app geschlossen, synchronisation, push, benachrichtigungen, wenig, minimal, akku'),
('de', 'faq_dislike_background_music', 'Was, wenn mir die Musik bei den Subliminals nicht gefällt?', 'Das ist natürlich Geschmackssache. Wir versuchen, eine breite Auswahl anzubieten, teils auch mit verschiedenen Hintergründen (Musik, Natur, reine Töne). Schau in die Audiobeschreibung oder nutze Filter. Dein Feedback hilft uns bei der Auswahl zukünftiger Sounds!', 'musik, hintergrundmusik, gefällt nicht, geschmack, alternative, auswahl, naturgeräusche, reine töne, ohne musik, feedback, variation'),
('de', 'faq_affirmation_voice_gender', 'Sind die Affirmationen mit männlicher oder weiblicher Stimme?', 'Das variiert. Einige Affirmationen werden von einer männlichen, andere von einer weiblichen Stimme gesprochen, manche sind vielleicht auch neutral oder synthetisch. Oft steht ein Hinweis dazu in der Beschreibung des Audios.', 'affirmationen, stimme, sprecher, geschlecht, männlich, weiblich, neutral, audio, beschreibung, inhalt, präferenz'),
('de', 'faq_request_specific_frequency', 'Kann ich eine bestimmte Binaural Beat Frequenz anfordern?', 'Eine individuelle Frequenzauswahl ist derzeit nicht möglich. Unsere Tracks nutzen sorgfältig ausgewählte Frequenzen passend zum jeweiligen Ziel (z.B. 4Hz für Tiefenentspannung). Teile uns aber gerne mit, welche Frequenzbereiche dich besonders interessieren!', 'binaural beats, frequenz, spezifisch, anfordern, wünschen, auswählen, einstellen, feature, feedback, hertz, gehirnwellen'),
('de', 'faq_trial_ended_early', 'Meine kostenlose Testphase ist unerwartet abgelaufen.', 'Oh, das sollte nicht passieren. Bitte prüfe das genaue Ablaufdatum in der Bestätigungsmail oder in deinen Store-Abo-Einstellungen (Apple/Google). Wenn das Datum noch nicht erreicht war, kontaktiere bitte den Support des Stores, über den du das Probeabo abgeschlossen hast.', 'testphase, probeabo, abgelaufen, zu früh, unerwartet, fehler, problem, abo, status, support, hilfe, store, apple, google'),
('de', 'faq_confirm_cancellation', 'Wie weiß ich sicher, dass mein Abo gekündigt ist?', 'Du erhältst eine Kündigungsbestätigung per E-Mail. Zudem ändert sich der Status in deinen Abo-Einstellungen (z.B. "Läuft aus am [Datum]" statt "Verlängert sich am [Datum]"). Prüfe beides!', 'kündigung, bestätigung, sicher sein, status, abo, abonnement, gekündigt, auslaufen, keine verlängerung, profil, überprüfen, email'),
('de', 'faq_student_discount', 'Gibt es einen Rabatt für Studenten?', 'Aktuell bieten wir keinen speziellen Studentenrabatt an. Schau aber auf der Upgrade-Seite nach, ob es eventuell zeitlich begrenzte Aktionen oder vergünstigte Jahresabos gibt.', 'rabatt, studenten, schüler, auszubildende, discount, angebot, preisnachlass, ermäßigung, kosten, abo, studentenrabatt'),
('de', 'faq_feedback_rejected', 'Warum wurde mein Feedback abgelehnt oder nicht umgesetzt?', 'Wir lesen jedes Feedback! Aber wir müssen Prioritäten setzen basierend auf vielen Faktoren: technische Machbarkeit, Nutzen für die Mehrheit der User, Ausrichtung auf unsere Produktstrategie. Auch wenn dein Vorschlag nicht direkt umgesetzt wird, fließt er in unsere Überlegungen ein. Danke dafür!', 'feedback, vorschlag, idee, abgelehnt, nicht umgesetzt, warum, grund, priorisierung, roadmap, strategie, danke'),
('de', 'faq_downloads_after_expiration', 'Was passiert mit meinen Downloads, wenn mein Premium-Abo ausläuft?', 'Die Lizenz zum Abspielen der heruntergeladenen Inhalte ist an dein aktives Premium-Abo gekoppelt. Läuft das Abo aus, können die Downloads nicht mehr abgespielt werden, auch wenn die Dateien noch auf dem Gerät sind. Sie müssen dann gelöscht werden.', 'download, offline, abo abgelaufen, premium ende, zugriff, hören, abspielen, nicht mehr verfügbar, gelöscht, lizenz'),
('de', 'faq_smart_tv_usage', 'Kann ich die App auf meinem Smart TV nutzen?', 'Wir haben keine spezielle Smart TV App. Du kannst aber versuchen, den Ton von deinem Handy/Tablet via Bluetooth, Chromecast oder AirPlay an deinen Fernseher oder eine verbundene Soundbar zu senden.', 'smart tv, fernseher, app, nutzen, installation, kompatibel, streaming, casting, bluetooth, airplay, chromecast, soundbar'),
('de', 'faq_account_verification', 'Muss ich mein Konto verifizieren?', 'Ja, die Bestätigung deiner E-Mail-Adresse nach der Registrierung ist ein wichtiger Sicherheitsschritt. Klicke einfach auf den Link in der E-Mail, die wir dir senden. Das hilft uns sicherzustellen, dass du es wirklich bist.', 'konto verifizieren, verifizierung, email bestätigen, bestätigung, registrierung, anmeldung, sicherheit, schritt, link, email'),
('de', 'faq_cancel_confirmation_missing', 'Ich habe gekündigt, aber keine Bestätigung erhalten.', 'Checke bitte deinen Spam-Ordner! Manchmal landen die Mails dort. Wenn nach 24h nichts da ist, prüfe den Abo-Status in deinem Profil. Sieht dort alles nach Kündigung aus? Wenn du unsicher bist, melde dich beim Support.', 'kündigung, bestätigung, email, nicht erhalten, fehlt, spam, abo status, profil, support, hilfe, problem'),
('de', 'faq_why_headphones_binaural', 'Warum genau braucht man Kopfhörer für Binaural Beats?', 'Weil der Effekt im Gehirn entsteht! Jedes Ohr bekommt einen leicht anderen Ton (z.B. 100Hz links, 104Hz rechts). Nur mit Stereo-Kopfhörern kommen diese Töne getrennt an. Dein Gehirn nimmt dann die Differenz (hier 4Hz) als pulsierenden "Beat" wahr.', 'warum, kopfhörer, binaural beats, notwendig, erforderlich, technik, erklärung, frequenz, unterschied, ohr, stereo, gehirn, effekt, lautsprecher, differenzton'),
('de', 'faq_iso_vs_binaural_headphones', 'Brauche ich für isochrone Töne auch Kopfhörer?', 'Nein, im Gegensatz zu Binaural Beats benötigen isochrone Töne technisch keine Kopfhörer, da der pulsierende Effekt nicht durch Frequenzunterschiede zwischen den Ohren erzeugt wird. Sie können auch über Lautsprecher gehört werden, wobei Kopfhörer Ablenkungen reduzieren können.', 'isochrone töne, kopfhörer, brauchen, nötig, ohne, lautsprecher, technik, unterschied, binaural beats'),
('de', 'faq_subliminal_effectiveness_skeptic', 'Ich bin skeptisch, ob Subliminals wirklich funktionieren.', 'Skepsis ist verständlich. Die Wirkung ist subtil und wissenschaftlich nicht abschließend geklärt. Wir empfehlen, es selbst auszuprobieren und offen für die Möglichkeit zu sein. Viele Nutzer berichten von positiven Erfahrungen bei regelmäßiger Anwendung. Es ist jedoch kein Wundermittel.', 'skeptisch, skepsis, funktioniert das, wirkung, zweifel, glaube, wissenschaft, beweis, erfahrung, placebo'),
('de', 'faq_family_plan_location', 'Müssen Mitglieder des Familienplans im selben Land leben?', 'Die Bedingungen für Familienpläne sehen meist vor, dass alle Mitglieder im selben Haushalt leben, was oft auch bedeutet, im selben Land. Genaue Details zu den Nutzungsbedingungen des Familienplans findest du in den Abo-Informationen.', 'familienplan, family plan, land, standort, haushalt, wohnsitz, bedingungen, agb, voraussetzung, regel'),
('de', 'faq_subscription_gift_card', 'Kann ich mit einer App Store / Google Play Geschenkkarte bezahlen?', 'Ob du dein Abonnement über das Guthaben einer Geschenkkarte deines App Stores (Apple App Store oder Google Play Store) bezahlen kannst, hängt von den Richtlinien des jeweiligen Stores ab. Oft ist dies möglich, wenn du die Karte deinem Store-Konto hinzufügst.', 'zahlung, bezahlen, geschenkkarte, guthabenkarte, app store, google play, itunes, guthaben, abo, möglich'),
('de', 'faq_delete_data_vs_account', 'Was ist der Unterschied zwischen Daten löschen und Konto löschen?', '''Konto löschen'' entfernt dein gesamtes Benutzerkonto inklusive Login, Profil, Playlists und verknüpften Abos unwiderruflich. ''Daten löschen'' bezieht sich oft spezifischer auf das Entfernen bestimmter Nutzungsdaten oder des Profilinhalts gemäß DSGVO, ohne zwingend den Account selbst zu deaktivieren (Details siehe Datenschutzerklärung).', 'unterschied, daten löschen, konto löschen, account, profil, dsgvo, vergessenwerden, was passiert'),
('de', 'faq_new_content_notification_how', 'Wie werde ich über neue Inhalte benachrichtigt?', 'Aktiviere die Push-Benachrichtigungen für ''Neue Inhalte'' in den App-Einstellungen (im Profil). Alternativ kannst du unseren Newsletter abonnieren oder uns auf Social Media folgen, wo wir ebenfalls Neuigkeiten posten.', 'neue inhalte, benachrichtigung, notification, push, info, wie erfahren, updates, newsletter, social media, einstellungen'),
('de', 'faq_playlist_automatic', 'Gibt es auch automatisch generierte Playlists?', 'Ja, oft bieten wir auch von uns kuratierte oder automatisch generierte Playlists an, basierend auf Themen, Stimmungen oder deinem Hörverhalten (z.B. ''Deine Mixe der Woche''). Diese findest du meist im ''Entdecken''-Bereich.', 'playlist, wiedergabeliste, automatisch, generiert, kuratiert, empfehlung, mix, vorschlag, entdecken'),
('de', 'faq_casting_to_speakers', 'Kann ich den Ton an Bluetooth-Lautsprecher oder Smart Speaker senden?', 'Ja, du kannst den Ton von deinem Smartphone oder Tablet normalerweise über Bluetooth an kompatible Lautsprecher oder Smart Speaker (wie Google Home, Amazon Echo) übertragen. Eine direkte Integration oder Steuerung über diese Speaker ist aber meist nicht vorhanden.', 'bluetooth lautsprecher, smart speaker, google home, amazon echo, alexa, cast, casting, übertragen, streaming, audio, sound'),
('de', 'faq_why_affirmations_positive', 'Warum sind die Affirmationen immer positiv formuliert?', 'Das Unterbewusstsein verarbeitet Verneinungen oft nicht gut. Positive Formulierungen (z.B. ''Ich bin ruhig'' statt ''Ich bin nicht gestresst'') sind direkter und klarer für das Unterbewusstsein zu verstehen und zu verankern.', 'affirmationen, positiv, formulierung, warum, grund, keine verneinung, unterbewusstsein, wirkung, sprache'),
('de', 'faq_subscription_benefits_change', 'Können sich die Vorteile meines Premium-Abos ändern?', 'Wir behalten uns vor, die Inhalte und Funktionen unserer Abopläne anzupassen, um die App weiterzuentwickeln. Wesentliche Änderungen an bestehenden Premium-Vorteilen würden wir jedoch rechtzeitig kommunizieren. Deine Kernvorteile bleiben in der Regel während deiner Laufzeit bestehen.', 'premium vorteile, änderung, abo, bedingungen, zukunft, anpassen, funktionen, inhalte'),
('de', 'faq_specific_subliminal_topic', 'Ich suche ein Subliminal zu einem ganz spezifischen Thema (z.B. Flugangst).', 'Nutze die Suchfunktion mit deinem spezifischen Thema. Wenn du nichts Passendes findest, decken unsere allgemeineren Audios zu verwandten Bereichen (z.B. Angstbewältigung, Selbstvertrauen) das Thema möglicherweise indirekt mit ab. Du kannst uns auch gerne einen Themenwunsch über die Feedback-Funktion senden.', 'spezifisches thema, suchen, finden, subliminal, inhalt, wunsch, flugangst, prüfungsangst, höhenangst, feedback'),
('de', 'faq_offline_playback_issues', 'Meine heruntergeladenen Audios spielen offline nicht.', 'Stelle sicher, dass der Download vollständig abgeschlossen wurde und die Datei nicht beschädigt ist. Prüfe, ob dein Premium-Abo noch aktiv ist, da Offline-Zugriff daran gebunden ist. Ein Neustart der App oder ein erneuter Download können helfen. Kontaktiere sonst den Support.', 'offline, download, fehler, spielt nicht, problem, premium, wiedergabe, datei, neustart, support, troubleshooting'),
('de', 'faq_app_permissions', 'Welche Berechtigungen braucht die App?', 'Die App benötigt normalerweise grundlegende Berechtigungen wie Internetzugriff (für Streaming/Sync). Für Downloads wird Speicherzugriff benötigt. Optional können Mikrofonzugriff (falls Sprachsteuerung geplant) oder Benachrichtigungsberechtigungen angefordert werden. Wir fragen nur nach Berechtigungen, die für die Funktion notwendig sind.', 'berechtigungen, permissions, app, datenschutz, funktion, internet, speicher, mikrofon, standort, zugriff'),
('de', 'faq_binaural_beats_risks', 'Gibt es Risiken bei Binaural Beats?', 'Für die meisten gesunden Erwachsenen gelten Binaural Beats bei moderater Lautstärke als sicher. Personen mit Epilepsie, Herzschrittmachern oder bestimmten neurologischen/psychischen Erkrankungen sollten jedoch vor der Anwendung unbedingt ihren Arzt konsultieren, da die Gehirnwellenstimulation unerwünschte Effekte haben könnte.', 'binaural beats, risiken, sicherheit, nebenwirkungen, warnung, gesundheit, epilepsie, herzschrittmacher, neurologisch, psychisch, arzt'),
('de', 'faq_vat_id_input', 'Wofür ist das Feld für die Umsatzsteuer-ID (VAT ID)?', 'Das Feld für die Umsatzsteuer-Identifikationsnummer (VAT ID) ist für Geschäftskunden innerhalb der EU relevant. Wenn du als Unternehmen bestellst und eine gültige VAT ID angibst, kann die Rechnung entsprechend ohne Umsatzsteuer ausgestellt werden (Reverse-Charge-Verfahren).', 'umsatzsteuer id, vat id, ust id, rechnung, geschäftskunde, eu, firma, unternehmen, reverse charge, steuer'),
('de', 'faq_update_billing_address', 'Wie aktualisiere ich meine Rechnungsadresse?', 'Deine Rechnungsadresse kannst du normalerweise in deinem Profil im Bereich ''Abonnement'' oder ''Abrechnungsinformationen'' ändern und speichern.', 'rechnungsadresse, adresse ändern, konto, profil, abo, aktualisieren, daten, abrechnung'),
('de', 'faq_email_change_impact', 'Was passiert, wenn ich meine E-Mail-Adresse ändere?', 'Wenn du deine E-Mail-Adresse änderst, wird diese zur neuen primären Adresse für deinen Login und für alle Benachrichtigungen von uns. Du musst dich zukünftig mit der neuen Adresse anmelden. Möglicherweise musst du die neue Adresse zuerst bestätigen.', 'email ändern, auswirkung, login, konto, benachrichtigung, was passiert, benutzername, bestätigung'),
('de', 'faq_cancel_refund_appstore', 'Ich habe über den App Store / Google Play abonniert, wie kündige oder storniere ich?', 'Abonnements, die direkt über den Apple App Store oder Google Play Store abgeschlossen wurden, müssen auch dort verwaltet und gekündigt werden. Öffne die Abonnementeinstellungen in deinem jeweiligen Store-Konto auf deinem Gerät.', 'kündigen, abo, app store, google play, ios, android, stornieren, verwalten, einstellungen, store konto'),
('de', 'faq_customer_support_languages', 'In welchen Sprachen bietet ihr Kundensupport an?', 'Unser Kundensupport kommuniziert primär auf Deutsch und Englisch. Wir versuchen aber, auch Anfragen in anderen Sprachen bestmöglich zu verstehen und zu beantworten, eventuell mithilfe von Übersetzungstools.', 'support, sprachen, kundendienst, hilfe, international, deutsch, englisch, kundenservice'),
('de', 'faq_app_permissions_explained', 'Könnt ihr die benötigten App-Berechtigungen genauer erklären?', 'Gerne. Internet wird für Streaming und Kontosynchronisation benötigt. Speicherzugriff ist nur für Offline-Downloads (Premium) erforderlich. Andere Berechtigungen wie Mikrofon oder Standort fragen wir standardmäßig nicht an, es sei denn, eine zukünftige Funktion würde dies erfordern und wir würden dich explizit um Erlaubnis bitten.', 'berechtigungen, permissions, erklärung, datenschutz, app, internet, speicher, mikrofon, standort, zugriff, warum, notwendig');
